#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/flash.h>
#include <zephyr/storage/stream_flash.h>
#include <zephyr/ztest.h>
#include <string.h>

#define LOG_LEVEL CONFIG_STREAM_FLASH_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(stream_flash_test);

#define TEST_WRITE_BUFFER_SIZE CONFIG_STREAM_FLASH_TEST_WRITE_BUFFER_SIZE

static struct stream_flash_ctx sf;
static const struct device *flash_dev;
static off_t test_region_offset;
static size_t test_region_size;

static void stream_flash_setup(void)
{
    flash_dev = DEVICE_DT_GET(DT_CHOSEN(zephyr_flash_controller));
    zassert_true(device_is_ready(flash_dev), "Flash device is not ready");

    const struct flash_parameters *flash_params = flash_get_parameters(flash_dev);
    zassert_not_null(flash_params, "Failed to get flash parameters");

    size_t write_block_size = flash_params->write_block_size;
    size_t total_flash_size = flash_params->size;

    // Set the test region to start at offset 0.
    test_region_offset = 0;

    // Calculate a safe test region size:
    // 1. Start with a generous desired size (e.g., 8 erase blocks).
    // 2. Cap it to the total available flash size.
    // 3. Round it down to the nearest multiple of the write block size,
    //    as stream_flash_init requires the size to be a multiple of write_block_size.
    // 4. Ensure a minimum size for tests (e.g., at least 2 write blocks for multi-page tests).
    // 5. Handle edge cases where flash is very small or parameters are zero.

    size_t desired_test_size = 8 * flash_params->erase_block_size;
    if (desired_test_size == 0) {
        desired_test_size = 8 * write_block_size;
    }
    if (desired_test_size == 0) {
        desired_test_size = 0x4000; /* Fallback to 16KB if block sizes are zero */
    }

    test_region_size = MIN(desired_test_size, total_flash_size);

    if (write_block_size > 0) {
        test_region_size = (test_region_size / write_block_size) * write_block_size;
    }

    // Ensure a minimum size for tests, e.g., at least 2 write blocks for multi-page tests.
    // Only apply if the total flash size can accommodate it.
    size_t min_required_size = 2 * write_block_size;
    if (min_required_size == 0) {
        min_required_size = 0x1000; /* Fallback to 4KB if write_block_size is zero */
    }

    if (test_region_size < min_required_size && total_flash_size >= min_required_size) {
        test_region_size = min_required_size;
    }

    // Final checks for very small or misconfigured flash
    if (test_region_size == 0 && total_flash_size > 0) {
        // If rounding or capping made it zero, but flash has size, use what's available
        test_region_size = total_flash_size;
        if (write_block_size > 0) {
            test_region_size = (test_region_size / write_block_size) * write_block_size;
        }
        if (test_region_size == 0 && write_block_size > 0) {
            test_region_size = write_block_size;
        }
    }
    if (test_region_size == 0) {
        test_region_size = 1; /* Absolute minimum non-zero size */
    }

    LOG_INF("Using test region: offset=0x%lx, size=0x%lx (total flash: 0x%lx, write_block: 0x%lx)",
            (long)test_region_offset, (long)test_region_size, (long)total_flash_size, (long)write_block_size);
}

static void stream_flash_teardown(void)
{
    /* No specific teardown needed for the device itself */
}

/* Test cases */

static void lib_stream_flash_test_stream_flash_init(void)
{
    int rc = stream_flash_init(&sf, flash_dev, test_region_offset, test_region_size, TEST_WRITE_BUFFER_SIZE);
    /* Line 129: Assertion failed here */
    zassert_not_equal(rc, -EFAULT, "stream_flash_init failed unexpectedly with -EFAULT");
    zassert_equal(rc, 0, "stream_flash_init failed with %d", rc);
}

